//! Reads the vendored androidx token files.
//!
//! They are Kotlin generated by Google's token tooling, so their shape is small and regular: a header, then one
//! `internal object <Name> { ... }` holding `const val` numbers, `inline val` getters and `val` shapes. This reader
//! accepts exactly the forms listed in [`Value`] and rejects every other line with its number, so a form it does not
//! know is never skipped or guessed: support for it is added on purpose, with a test.

use std::collections::HashSet;
use std::fmt;

/// One token file: `internal object <name> { ... }`.
#[derive(Debug, PartialEq)]
pub(crate) struct TokenObject {
    /// The object's name, such as `MotionTokens`.
    pub(crate) name: String,
    /// The `// VERSION:` header, such as `v0_103`, when the file has one.
    pub(crate) version: Option<String>,
    /// The tokens, in file order.
    pub(crate) tokens: Vec<Token>,
}

/// One token: a name and its value.
#[derive(Debug, PartialEq)]
pub(crate) struct Token {
    /// The Kotlin name, such as `DurationShort1`.
    pub(crate) name: String,
    /// The value.
    pub(crate) value: Value,
}

/// The token values this reader understands.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Value {
    /// `const val X = 0.8f` (a Kotlin `Float`) or `const val X = 700.0` (a Kotlin `Double` that `f32` holds
    /// exactly; NSH takes `f32`).
    Number(f32),
    /// `inline val X: CubicBezierEasing` / `get() = CubicBezierEasing(x1, y1, x2, y2)`.
    CubicBezier([f32; 4]),
    /// `inline val X: Color` / `get() = Color(red = 0, green = 0, blue = 0)`: an opaque 8-bit sRGB color.
    Srgb([u8; 3]),
    /// `inline val X: androidx.compose.ui.unit.Dp` / `get() = 6.0.dp`, or `val X = CornerSize(4.0.dp)`: a length in
    /// density-independent pixels, which is NSH's point.
    Dp(f32),
    /// `val X = RectangleShape`, `val X = CircleShape` or `val X = RoundedCornerShape(...)`, on one line or over
    /// several.
    Shape(Shape),
    /// `inline val X: androidx.compose.ui.graphics.Color` / `get() = PaletteTokens.Neutral98`: the color of
    /// another token, of another object or, written `get() = Primary`, of the same one.
    Color(Reference),
}

/// A shape, as androidx builds one.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Shape {
    /// `RectangleShape`: square corners.
    Rectangle,
    /// `CircleShape`: each corner rounded by half the shorter side.
    Circle,
    /// `RoundedCornerShape(4.0.dp)`, the same radius at every corner, or `RoundedCornerShape(topStart = 4.0.dp,
    /// topEnd = 4.0.dp, bottomEnd = 0.0.dp, bottomStart = 0.0.dp)`: the radius at each corner, in that order.
    Rounded([f32; 4]),
}

/// A token of another object, such as `PaletteTokens.Neutral98`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Reference {
    /// The object, such as `PaletteTokens`.
    pub(crate) object: String,
    /// The token, such as `Neutral98`.
    pub(crate) token: String,
}

/// Why a file was rejected, and on which line (1-based).
#[derive(Debug, PartialEq)]
pub(crate) struct ParseError {
    pub(crate) line: usize,
    pub(crate) kind: ParseErrorKind,
}

#[derive(Debug, PartialEq)]
pub(crate) enum ParseErrorKind {
    /// A line whose form this reader does not support.
    Unsupported(String),
    /// A token name that is not a plain `PascalCase` identifier.
    BadName(String),
    /// A number that is not a plain decimal literal, or an integer.
    BadNumber(String),
    /// A color channel that is not a plain integer from 0 to 255.
    BadChannel(String),
    /// A `Double` that `f32` cannot hold exactly.
    Inexact(String),
    /// An `inline val` not followed by its `get() = ...` line.
    MissingGetter(String),
    /// A `val X =` whose value never closes its parentheses.
    UnclosedValue(String),
    /// The same token name twice.
    Duplicate(String),
    /// Something after the object's closing brace.
    TrailingContent(String),
    /// The file has no `internal object`, or it never closes.
    Unterminated,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "line {}: ", self.line)?;
        match &self.kind {
            ParseErrorKind::Unsupported(text) => write!(f, "unsupported form `{text}`"),
            ParseErrorKind::BadName(name) => write!(f, "`{name}` is not a PascalCase token name"),
            ParseErrorKind::BadNumber(text) => write!(f, "`{text}` is not a supported number"),
            ParseErrorKind::BadChannel(text) => {
                write!(f, "`{text}` is not a color channel from 0 to 255")
            }
            ParseErrorKind::Inexact(text) => write!(f, "`{text}` cannot be held exactly by an f32"),
            ParseErrorKind::MissingGetter(name) => write!(f, "`{name}` has no `get() = ...` line"),
            ParseErrorKind::UnclosedValue(name) => write!(f, "`{name}`'s value never closes"),
            ParseErrorKind::Duplicate(name) => write!(f, "`{name}` is defined twice"),
            ParseErrorKind::TrailingContent(text) => write!(f, "`{text}` after the object's end"),
            ParseErrorKind::Unterminated => write!(f, "no complete `internal object` in the file"),
        }
    }
}

enum State {
    Header,
    Body,
    Getter {
        name: String,
        ty: String,
    },
    /// Inside `val <name> =`, whose value spans lines: `expression` holds them so far, trimmed and joined.
    Value {
        name: String,
        expression: String,
    },
    Done,
}

/// Reads one token file.
pub(crate) fn parse(source: &str) -> Result<TokenObject, ParseError> {
    let mut object = TokenObject {
        name: String::new(),
        version: None,
        tokens: Vec::new(),
    };
    let mut seen = HashSet::new();
    let mut state = State::Header;
    let mut last_line = 0;
    for (index, raw) in source.lines().enumerate() {
        let line = index + 1;
        last_line = line;
        let text = raw.trim();
        let error = |kind| ParseError { line, kind };
        state = match state {
            State::Header => header_line(text, &mut object).map_err(error)?,
            State::Body => match body_line(text).map_err(error)? {
                BodyLine::Blank => State::Body,
                BodyLine::End => State::Done,
                BodyLine::Token(token) => {
                    push(&mut object, &mut seen, token).map_err(error)?;
                    State::Body
                }
                BodyLine::Getter { name, ty } => State::Getter { name, ty },
                BodyLine::Value { name } => State::Value {
                    name,
                    expression: String::new(),
                },
            },
            State::Getter { name, ty } => {
                let token = getter_line(text, name, &ty, &object.name).map_err(error)?;
                push(&mut object, &mut seen, token).map_err(error)?;
                State::Body
            }
            State::Value {
                name,
                mut expression,
            } => {
                expression.push_str(text);
                if is_closed(&expression) {
                    let value = value_expression(&expression).map_err(error)?;
                    push(&mut object, &mut seen, Token { name, value }).map_err(error)?;
                    State::Body
                } else {
                    State::Value { name, expression }
                }
            }
            State::Done if text.is_empty() => State::Done,
            State::Done => return Err(error(ParseErrorKind::TrailingContent(text.to_owned()))),
        };
    }
    match state {
        State::Done => Ok(object),
        State::Getter { name, .. } => Err(ParseError {
            line: last_line,
            kind: ParseErrorKind::MissingGetter(name),
        }),
        State::Value { name, .. } => Err(ParseError {
            line: last_line,
            kind: ParseErrorKind::UnclosedValue(name),
        }),
        State::Header | State::Body => Err(ParseError {
            line: last_line,
            kind: ParseErrorKind::Unterminated,
        }),
    }
}

fn header_line(text: &str, object: &mut TokenObject) -> Result<State, ParseErrorKind> {
    if let Some(version) = text.strip_prefix("// VERSION:") {
        object.version = Some(version.trim().to_owned());
        return Ok(State::Header);
    }
    let is_comment = text.starts_with("/*") || text.starts_with('*') || text.starts_with("//");
    if text.is_empty() || is_comment || text.starts_with("package ") || text.starts_with("import ")
    {
        return Ok(State::Header);
    }
    let name = text
        .strip_prefix("internal object ")
        .and_then(|rest| rest.strip_suffix(" {"))
        .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
    object.name = checked_name(name)?;
    Ok(State::Body)
}

enum BodyLine {
    Blank,
    End,
    Token(Token),
    Getter {
        name: String,
        ty: String,
    },
    /// `val <name> =`, its value on the lines after.
    Value {
        name: String,
    },
}

fn body_line(text: &str) -> Result<BodyLine, ParseErrorKind> {
    if text.is_empty() {
        return Ok(BodyLine::Blank);
    }
    if text == "}" {
        return Ok(BodyLine::End);
    }
    if let Some(rest) = text.strip_prefix("const val ") {
        let (name, literal) = rest
            .split_once(" = ")
            .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
        return Ok(BodyLine::Token(Token {
            name: checked_name(name)?,
            value: Value::Number(number(literal)?),
        }));
    }
    if let Some(rest) = text.strip_prefix("inline val ") {
        let (name, ty) = rest
            .split_once(": ")
            .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
        return Ok(BodyLine::Getter {
            name: checked_name(name)?,
            ty: ty.to_owned(),
        });
    }
    if let Some(rest) = text.strip_prefix("val ") {
        if let Some(name) = rest.strip_suffix(" =") {
            return Ok(BodyLine::Value {
                name: checked_name(name)?,
            });
        }
        let (name, expression) = rest
            .split_once(" = ")
            .ok_or_else(|| ParseErrorKind::Unsupported(text.to_owned()))?;
        let name = checked_name(name)?;
        // A value that opens a parenthesis it does not close on this line is not a form these files use.
        if !is_closed(expression) {
            return Err(ParseErrorKind::Unsupported(text.to_owned()));
        }
        let value = value_expression(expression).map_err(|error| match error {
            ParseErrorKind::Unsupported(_) => ParseErrorKind::Unsupported(text.to_owned()),
            other => other,
        })?;
        return Ok(BodyLine::Token(Token { name, value }));
    }
    Err(ParseErrorKind::Unsupported(text.to_owned()))
}

/// Whether `expression` is complete: not empty, and every parenthesis it opens is closed.
fn is_closed(expression: &str) -> bool {
    !expression.is_empty() && expression.matches('(').count() == expression.matches(')').count()
}

/// The value of a `val`: a shape or a corner size.
fn value_expression(expression: &str) -> Result<Value, ParseErrorKind> {
    let unsupported = || ParseErrorKind::Unsupported(expression.to_owned());
    match expression {
        "RectangleShape" => return Ok(Value::Shape(Shape::Rectangle)),
        "CircleShape" => return Ok(Value::Shape(Shape::Circle)),
        _ => {}
    }
    if let Some(argument) = expression
        .strip_prefix("CornerSize(")
        .and_then(|rest| rest.strip_suffix(')'))
    {
        return Ok(Value::Dp(dp(argument).ok_or_else(unsupported)??));
    }
    let arguments = expression
        .strip_prefix("RoundedCornerShape(")
        .and_then(|rest| rest.strip_suffix(')'))
        .ok_or_else(unsupported)?;
    // Kotlin allows a trailing comma, and the generated files put one after the last named argument.
    let arguments: Vec<&str> = arguments
        .strip_suffix(',')
        .unwrap_or(arguments)
        .split(',')
        .map(str::trim)
        .collect();
    // One argument is the radius of every corner, unless it is named: one named corner is not a form these files use.
    let radii = if let [radius] = arguments.as_slice()
        && !radius.contains('=')
    {
        let radius = dp(radius).ok_or_else(unsupported)??;
        [radius; 4]
    } else {
        let labels = ["topStart = ", "topEnd = ", "bottomEnd = ", "bottomStart = "];
        if arguments.len() != labels.len() {
            return Err(unsupported());
        }
        let mut radii = [0.0; 4];
        for ((radius, argument), label) in radii.iter_mut().zip(&arguments).zip(labels) {
            let length = argument.strip_prefix(label).ok_or_else(unsupported)?;
            *radius = dp(length).ok_or_else(unsupported)??;
        }
        radii
    };
    Ok(Value::Shape(Shape::Rounded(radii)))
}

/// `4.0.dp`, as a number of points; `None` when the expression is not a length in dp.
fn dp(expression: &str) -> Option<Result<f32, ParseErrorKind>> {
    expression.strip_suffix(".dp").map(number)
}

/// The value of `inline val <name>: <ty>`, from its `get() = ...` line, in the object named `object`.
fn getter_line(text: &str, name: String, ty: &str, object: &str) -> Result<Token, ParseErrorKind> {
    let Some(expression) = text.strip_prefix("get() = ") else {
        return Err(ParseErrorKind::MissingGetter(name));
    };
    let unsupported = || ParseErrorKind::Unsupported(text.to_owned());
    let value = match ty {
        "CubicBezierEasing" => curve(expression).ok_or_else(unsupported)??,
        "Color" | "androidx.compose.ui.graphics.Color" => match srgb(expression) {
            Some(channels) => Value::Srgb(channels?),
            None => Value::Color(reference(expression, object).ok_or_else(unsupported)??),
        },
        "androidx.compose.ui.unit.Dp" => Value::Dp(dp(expression).ok_or_else(unsupported)??),
        _ => return Err(unsupported()),
    };
    Ok(Token { name, value })
}

/// `CubicBezierEasing(x1, y1, x2, y2)`; `None` when the expression has another shape.
fn curve(expression: &str) -> Option<Result<Value, ParseErrorKind>> {
    let arguments = expression
        .strip_prefix("CubicBezierEasing(")?
        .strip_suffix(')')?;
    let numbers = match arguments
        .split(", ")
        .map(number)
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(numbers) => numbers,
        Err(error) => return Some(Err(error)),
    };
    let points: [f32; 4] = numbers.try_into().ok()?;
    Some(Ok(Value::CubicBezier(points)))
}

/// `Color(red = 0, green = 0, blue = 0)`; `None` when the expression is not a `Color(...)` call of exactly these
/// three named channels, in this order.
fn srgb(expression: &str) -> Option<Result<[u8; 3], ParseErrorKind>> {
    let arguments = expression.strip_prefix("Color(")?.strip_suffix(')')?;
    let mut channels = [0_u8; 3];
    let mut parts = arguments.split(", ");
    for (channel, label) in channels.iter_mut().zip(["red = ", "green = ", "blue = "]) {
        let literal = parts.next()?.strip_prefix(label)?;
        match self::channel(literal) {
            Ok(value) => *channel = value,
            Err(error) => return Some(Err(error)),
        }
    }
    if parts.next().is_some() {
        return None;
    }
    Some(Ok(channels))
}

/// `PaletteTokens.Neutral98`, a token of another object, or `Primary`, a token of `object` itself; `None` when the
/// expression is neither.
fn reference(expression: &str, object: &str) -> Option<Result<Reference, ParseErrorKind>> {
    let (owner, token) = expression.split_once('.').unwrap_or((object, expression));
    // A second dot (`a.b.C`) or a call (`X.copy(...)`) is another form, not a bad name.
    if token.is_empty() || !token.chars().all(|c| c.is_ascii_alphanumeric()) {
        return None;
    }
    Some(checked_name(owner).and_then(|object| {
        Ok(Reference {
            object,
            token: checked_name(token)?,
        })
    }))
}

fn push(
    object: &mut TokenObject,
    seen: &mut HashSet<String>,
    token: Token,
) -> Result<(), ParseErrorKind> {
    if !seen.insert(token.name.clone()) {
        return Err(ParseErrorKind::Duplicate(token.name));
    }
    object.tokens.push(token);
    Ok(())
}

fn checked_name(name: &str) -> Result<String, ParseErrorKind> {
    let mut chars = name.chars();
    let starts_upper = chars.next().is_some_and(|c| c.is_ascii_uppercase());
    if starts_upper && chars.all(|c| c.is_ascii_alphanumeric()) {
        Ok(name.to_owned())
    } else {
        Err(ParseErrorKind::BadName(name.to_owned()))
    }
}

/// A Kotlin `Float` (`0.8f`) or `Double` (`700.0`) literal, as the `f32` NSH takes.
fn number(literal: &str) -> Result<f32, ParseErrorKind> {
    let bad = || ParseErrorKind::BadNumber(literal.to_owned());
    let (digits, is_float) = match literal.strip_suffix('f') {
        Some(digits) => (digits, true),
        None => (literal, false),
    };
    // Only plain decimals with a fraction: Rust's parser would also take `inf`, `NaN` or `1e5`, and an integer
    // literal is a Kotlin `Int` this reader has no use for yet.
    let unsigned = digits.strip_prefix('-').unwrap_or(digits);
    let (whole, fraction) = unsigned.split_once('.').ok_or_else(bad)?;
    let all_digits = |part: &str| !part.is_empty() && part.chars().all(|c| c.is_ascii_digit());
    if !all_digits(whole) || !all_digits(fraction) {
        return Err(bad());
    }
    let narrow: f32 = digits.parse().map_err(|_| bad())?;
    if !is_float {
        let wide: f64 = digits.parse().map_err(|_| bad())?;
        if f64::from(narrow).to_bits() != wide.to_bits() {
            return Err(ParseErrorKind::Inexact(literal.to_owned()));
        }
    }
    Ok(narrow)
}

/// An 8-bit color channel: a plain integer from 0 to 255.
fn channel(literal: &str) -> Result<u8, ParseErrorKind> {
    let bad = || ParseErrorKind::BadChannel(literal.to_owned());
    // `u8::from_str` would also take a leading `+`.
    if !literal.chars().all(|c| c.is_ascii_digit()) {
        return Err(bad());
    }
    literal.parse().map_err(|_| bad())
}

#[cfg(test)]
mod tests {
    use super::*;

    const HEADER: &str = "/*\n * Copyright\n */\n// VERSION: v0_1\n// GENERATED CODE\n\npackage a.b\n\nimport a.C\n\n";

    fn file(body: &str) -> String {
        format!("{HEADER}internal object SampleTokens {{\n{body}}}\n")
    }

    fn error_kind(body: &str) -> ParseErrorKind {
        parse(&file(body)).unwrap_err().kind
    }

    #[test]
    fn reads_numbers_and_curves_in_file_order() {
        let source = file(
            "    const val DurationShort1 = 50.0\n    const val SpringDamping = 0.8f\n    inline val Easing: CubicBezierEasing\n        get() = CubicBezierEasing(0.2f, 0.0f, 0.0f, 1.0f)\n\n",
        );
        let object = parse(&source).unwrap();
        assert_eq!(object.name, "SampleTokens");
        assert_eq!(object.version.as_deref(), Some("v0_1"));
        assert_eq!(
            object.tokens,
            vec![
                Token {
                    name: "DurationShort1".into(),
                    value: Value::Number(50.0)
                },
                Token {
                    name: "SpringDamping".into(),
                    value: Value::Number(0.8)
                },
                Token {
                    name: "Easing".into(),
                    value: Value::CubicBezier([0.2, 0.0, 0.0, 1.0])
                },
            ]
        );
    }

    fn color(object: &str, token: &str) -> Value {
        Value::Color(Reference {
            object: object.into(),
            token: token.into(),
        })
    }

    fn only_value(body: &str) -> Value {
        let mut tokens = parse(&file(body)).unwrap().tokens;
        assert_eq!(tokens.len(), 1);
        tokens.remove(0).value
    }

    #[test]
    fn reads_colors_and_color_references() {
        let source = file(
            "    inline val Neutral98: Color\n        get() = Color(red = 254, green = 247, blue = 0)\n\n    inline val Background: androidx.compose.ui.graphics.Color\n        get() = PaletteTokens.Neutral98\n\n    inline val Error: Color\n        get() = PaletteTokens.Error40\n",
        );
        let tokens = parse(&source).unwrap().tokens;
        assert_eq!(
            tokens,
            vec![
                Token {
                    name: "Neutral98".into(),
                    value: Value::Srgb([254, 247, 0]),
                },
                Token {
                    name: "Background".into(),
                    value: color("PaletteTokens", "Neutral98"),
                },
                Token {
                    name: "Error".into(),
                    value: color("PaletteTokens", "Error40"),
                },
            ]
        );
    }

    #[test]
    fn keeps_each_channel_in_its_place() {
        assert_eq!(
            only_value(
                "    inline val C: Color\n        get() = Color(red = 1, green = 2, blue = 255)\n"
            ),
            Value::Srgb([1, 2, 255])
        );
    }

    #[test]
    fn rejects_a_channel_out_of_range_or_not_a_plain_integer() {
        for literal in ["256", "-1", "+1", "1.0", "0x10", "", "1f"] {
            assert_eq!(
                error_kind(&format!(
                    "    inline val C: Color\n        get() = Color(red = 0, green = {literal}, blue = 0)\n"
                )),
                ParseErrorKind::BadChannel(literal.into()),
                "{literal}"
            );
        }
        assert_eq!(channel("0"), Ok(0));
        assert_eq!(channel("255"), Ok(255));
    }

    #[test]
    fn rejects_a_color_call_of_another_shape() {
        for expression in [
            "Color(red = 0, green = 0)",
            "Color(red = 0, green = 0, blue = 0, alpha = 0)",
            "Color(green = 0, red = 0, blue = 0)",
            "Color(0, 0, 0)",
            "Color(0xFF000000)",
            "Color(red = 0, green = 0, blue = 0",
            "Primary()",
            "PaletteTokens.Neutral98.copy(alpha = 0.5f)",
            "PaletteTokens.",
            "a.b.C",
        ] {
            assert_eq!(
                error_kind(&format!(
                    "    inline val C: Color\n        get() = {expression}\n"
                )),
                ParseErrorKind::Unsupported(format!("get() = {expression}")),
                "{expression}"
            );
        }
    }

    #[test]
    fn a_bare_name_is_a_token_of_the_same_object() {
        assert_eq!(
            only_value("    inline val SurfaceTint: Color\n        get() = Primary\n"),
            color("SampleTokens", "Primary")
        );
        assert_eq!(
            error_kind("    inline val C: Color\n        get() = primary\n"),
            ParseErrorKind::BadName("primary".into())
        );
    }

    #[test]
    fn a_reference_names_two_pascal_case_identifiers() {
        assert_eq!(
            error_kind("    inline val C: Color\n        get() = paletteTokens.Neutral98\n"),
            ParseErrorKind::BadName("paletteTokens".into())
        );
        assert_eq!(
            error_kind("    inline val C: Color\n        get() = PaletteTokens.neutral98\n"),
            ParseErrorKind::BadName("neutral98".into())
        );
    }

    #[test]
    fn a_color_needs_a_color_type_and_a_reference_needs_a_color() {
        // The type decides the form: a color call or a reference under another type is not guessed.
        assert_eq!(
            error_kind("    inline val C: Dp\n        get() = PaletteTokens.Neutral98\n"),
            ParseErrorKind::Unsupported("get() = PaletteTokens.Neutral98".into())
        );
        assert_eq!(
            error_kind(
                "    inline val C: CubicBezierEasing\n        get() = Color(red = 0, green = 0, blue = 0)\n"
            ),
            ParseErrorKind::Unsupported("get() = Color(red = 0, green = 0, blue = 0)".into())
        );
        assert_eq!(
            error_kind(
                "    inline val C: ColorToken\n        get() = ColorSchemeKeyTokens.Primary\n"
            ),
            ParseErrorKind::Unsupported("get() = ColorSchemeKeyTokens.Primary".into())
        );
    }

    #[test]
    fn reads_lengths_in_dp() {
        assert_eq!(
            only_value(
                "    inline val Level2: androidx.compose.ui.unit.Dp\n        get() = 3.0.dp\n"
            ),
            Value::Dp(3.0)
        );
    }

    #[test]
    fn rejects_a_length_of_another_shape() {
        let error = |expression: &str| {
            error_kind(&format!(
                "    inline val L: androidx.compose.ui.unit.Dp\n        get() = {expression}\n"
            ))
        };
        assert_eq!(
            error("3.0"),
            ParseErrorKind::Unsupported("get() = 3.0".into())
        );
        assert_eq!(
            error("3.0.sp"),
            ParseErrorKind::Unsupported("get() = 3.0.sp".into())
        );
        assert_eq!(
            error("ElevationTokens.Level0"),
            ParseErrorKind::Unsupported("get() = ElevationTokens.Level0".into())
        );
        assert_eq!(error("3.dp"), ParseErrorKind::BadNumber("3".into()));
        assert_eq!(error("0.1.dp"), ParseErrorKind::Inexact("0.1".into()));
        // A `Dp` named by its short type is not a form these files use.
        assert_eq!(
            error_kind("    inline val L: Dp\n        get() = 3.0.dp\n"),
            ParseErrorKind::Unsupported("get() = 3.0.dp".into())
        );
    }

    #[test]
    fn reads_shapes_and_corner_sizes_on_one_line() {
        let source = file(
            "    val CornerFull = CircleShape\n    val CornerNone = RectangleShape\n    val CornerSmall = RoundedCornerShape(8.0.dp)\n    val CornerValueSmall = CornerSize(8.0.dp)\n",
        );
        let values: Vec<Value> = parse(&source)
            .unwrap()
            .tokens
            .into_iter()
            .map(|token| token.value)
            .collect();
        assert_eq!(
            values,
            [
                Value::Shape(Shape::Circle),
                Value::Shape(Shape::Rectangle),
                Value::Shape(Shape::Rounded([8.0; 4])),
                Value::Dp(8.0),
            ]
        );
    }

    #[test]
    fn reads_a_shape_over_several_lines_with_each_corner_in_place() {
        // androidx `ShapeTokens.CornerLargeEnd`: every corner is named, in this order, with a trailing comma.
        let body = "    val CornerLargeEnd =\n        RoundedCornerShape(\n            topStart = 0.0.dp,\n            topEnd = 16.0.dp,\n            bottomEnd = 12.0.dp,\n            bottomStart = 4.0.dp,\n        )\n    val CornerFull =\n        CircleShape\n";
        let tokens = parse(&file(body)).unwrap().tokens;
        assert_eq!(
            tokens,
            [
                Token {
                    name: "CornerLargeEnd".into(),
                    value: Value::Shape(Shape::Rounded([0.0, 16.0, 12.0, 4.0])),
                },
                Token {
                    name: "CornerFull".into(),
                    value: Value::Shape(Shape::Circle),
                },
            ]
        );
    }

    #[test]
    fn rejects_a_shape_of_another_form() {
        let unsupported = |expression: &str| {
            assert_eq!(
                error_kind(&format!("    val S = {expression}\n")),
                ParseErrorKind::Unsupported(format!("val S = {expression}")),
                "{expression}"
            );
        };
        // A percentage, a size in another unit, two radii, a corner out of androidx's order, a corner missing, an
        // unknown corner, a shape androidx has but these files do not use, and a number with no shape.
        unsupported("RoundedCornerShape(50)");
        unsupported("RoundedCornerShape(4.0.sp)");
        unsupported("RoundedCornerShape(4.0.dp, 8.0.dp)");
        unsupported("RoundedCornerShape(topStart = 4.0.dp)");
        unsupported(
            "RoundedCornerShape(topEnd = 4.0.dp, topStart = 4.0.dp, bottomEnd = 0.0.dp, bottomStart = 0.0.dp)",
        );
        unsupported("RoundedCornerShape(topStart = 4.0.dp, topEnd = 4.0.dp, bottomEnd = 0.0.dp)");
        unsupported(
            "RoundedCornerShape(topLeft = 4.0.dp, topEnd = 4.0.dp, bottomEnd = 0.0.dp, bottomStart = 0.0.dp)",
        );
        unsupported("CutCornerShape(4.0.dp)");
        unsupported("CornerSize(50)");
        unsupported("CornerSize(4.0.dp).copy()");
        unsupported("4.0");
        // A value that opens a parenthesis it does not close on its own line.
        unsupported("RoundedCornerShape(");
    }

    #[test]
    fn a_shape_with_a_bad_number_or_name_reports_it() {
        assert_eq!(
            error_kind("    val S = RoundedCornerShape(4.dp)\n"),
            ParseErrorKind::BadNumber("4".into())
        );
        assert_eq!(
            error_kind("    val S = CornerSize(0.1.dp)\n"),
            ParseErrorKind::Inexact("0.1".into())
        );
        assert_eq!(
            error_kind(
                "    val S =\n        RoundedCornerShape(\n            topStart = 4.dp,\n            topEnd = 4.0.dp,\n            bottomEnd = 0.0.dp,\n            bottomStart = 0.0.dp,\n        )\n"
            ),
            ParseErrorKind::BadNumber("4".into())
        );
        assert_eq!(
            error_kind("    val lower = CircleShape\n"),
            ParseErrorKind::BadName("lower".into())
        );
        assert_eq!(
            error_kind("    val lower =\n        CircleShape\n"),
            ParseErrorKind::BadName("lower".into())
        );
        assert_eq!(
            error_kind("    val S = CircleShape\n    val S = RectangleShape\n"),
            ParseErrorKind::Duplicate("S".into())
        );
    }

    #[test]
    fn a_shape_that_never_closes_is_an_error_at_the_last_line() {
        let source = format!(
            "{HEADER}internal object SampleTokens {{\n    val S =\n        RoundedCornerShape(\n"
        );
        let error = parse(&source).unwrap_err();
        assert_eq!(error.kind, ParseErrorKind::UnclosedValue("S".into()));
        assert_eq!(error.line, source.lines().count());
    }

    #[test]
    fn a_shape_over_several_lines_reports_the_line_that_closes_it() {
        let body =
            "    val S =\n        RoundedCornerShape(\n            topStart = 4.0.dp,\n        )\n";
        let error = parse(&file(body)).unwrap_err();
        assert_eq!(
            error.kind,
            ParseErrorKind::Unsupported("RoundedCornerShape(topStart = 4.0.dp,)".into())
        );
        let closing_line = HEADER.lines().count() + 5;
        assert_eq!(error.line, closing_line);
    }

    #[test]
    fn a_curve_with_a_bad_number_reports_the_number() {
        assert_eq!(
            error_kind(
                "    inline val E: CubicBezierEasing\n        get() = CubicBezierEasing(0.2f, 0.0f, x, 1.0f)\n"
            ),
            ParseErrorKind::BadNumber("x".into())
        );
    }

    #[test]
    fn a_float_literal_becomes_the_nearest_f32() {
        assert_eq!(number("0.8f").unwrap().to_bits(), 0.8_f32.to_bits());
        assert_eq!(number("-0.25f").unwrap().to_bits(), (-0.25_f32).to_bits());
    }

    #[test]
    fn rejects_a_double_that_f32_cannot_hold() {
        assert_eq!(number("0.1"), Err(ParseErrorKind::Inexact("0.1".into())));
        assert_eq!(number("700.0").unwrap().to_bits(), 700.0_f32.to_bits());
    }

    #[test]
    fn rejects_numbers_that_are_not_plain_decimals() {
        for literal in ["2", "1e5", "1.0e5f", "inf", "NaN", ".5f", "5.f", "0x10", ""] {
            assert_eq!(
                number(literal),
                Err(ParseErrorKind::BadNumber(literal.into())),
                "{literal}"
            );
        }
    }

    #[test]
    fn rejects_an_unknown_form_instead_of_skipping_it() {
        assert_eq!(
            error_kind("    val Shape = CutCornerShape(4.0.dp)\n"),
            ParseErrorKind::Unsupported("val Shape = CutCornerShape(4.0.dp)".into())
        );
        assert_eq!(
            error_kind("    inline val Size: Dp\n        get() = 4.0.dp\n"),
            ParseErrorKind::Unsupported("get() = 4.0.dp".into())
        );
        assert_eq!(
            error_kind(
                "    inline val E: CubicBezierEasing\n        get() = CubicBezierEasing(0.2f, 0.0f, 1.0f)\n"
            ),
            ParseErrorKind::Unsupported("get() = CubicBezierEasing(0.2f, 0.0f, 1.0f)".into())
        );
    }

    #[test]
    fn reports_the_line_of_the_error() {
        let error = parse(&file("    const val A = 1.0\n    const val B = oops\n")).unwrap_err();
        let line_of_b = HEADER.lines().count() + 3;
        assert_eq!(error.line, line_of_b);
    }

    #[test]
    fn rejects_bad_names_duplicates_and_trailing_content() {
        assert_eq!(
            error_kind("    const val lower = 1.0\n"),
            ParseErrorKind::BadName("lower".into())
        );
        assert_eq!(
            error_kind("    const val A = 1.0\n    const val A = 2.0\n"),
            ParseErrorKind::Duplicate("A".into())
        );
        let trailing = format!("{}val Stray = 1\n", file(""));
        assert_eq!(
            parse(&trailing).unwrap_err().kind,
            ParseErrorKind::TrailingContent("val Stray = 1".into())
        );
    }

    #[test]
    fn blank_lines_after_the_object_are_fine() {
        let source = format!("{}\n\n   \n", file("    const val A = 1.0\n"));
        assert_eq!(parse(&source).unwrap().tokens.len(), 1);
    }

    #[test]
    fn every_error_names_its_line_and_its_cause() {
        let cases = [
            (
                ParseErrorKind::Unsupported("x".into()),
                "line 3: unsupported form `x`",
            ),
            (
                ParseErrorKind::BadName("x".into()),
                "line 3: `x` is not a PascalCase token name",
            ),
            (
                ParseErrorKind::BadNumber("x".into()),
                "line 3: `x` is not a supported number",
            ),
            (
                ParseErrorKind::BadChannel("x".into()),
                "line 3: `x` is not a color channel from 0 to 255",
            ),
            (
                ParseErrorKind::Inexact("x".into()),
                "line 3: `x` cannot be held exactly by an f32",
            ),
            (
                ParseErrorKind::MissingGetter("x".into()),
                "line 3: `x` has no `get() = ...` line",
            ),
            (
                ParseErrorKind::UnclosedValue("x".into()),
                "line 3: `x`'s value never closes",
            ),
            (
                ParseErrorKind::Duplicate("x".into()),
                "line 3: `x` is defined twice",
            ),
            (
                ParseErrorKind::TrailingContent("x".into()),
                "line 3: `x` after the object's end",
            ),
            (
                ParseErrorKind::Unterminated,
                "line 3: no complete `internal object` in the file",
            ),
        ];
        for (kind, message) in cases {
            assert_eq!(ParseError { line: 3, kind }.to_string(), message);
        }
    }

    #[test]
    fn rejects_a_getter_without_its_body_and_an_unclosed_object() {
        assert_eq!(
            error_kind("    inline val E: CubicBezierEasing\n    const val A = 1.0\n"),
            ParseErrorKind::MissingGetter("E".into())
        );
        assert_eq!(
            parse("internal object A {\n    const val B = 1.0\n")
                .unwrap_err()
                .kind,
            ParseErrorKind::Unterminated
        );
        assert_eq!(
            parse("package a\n").unwrap_err().kind,
            ParseErrorKind::Unterminated
        );
    }
}
